#define I2C_MASTER_SDA_IO    21     // GPIO seguro
#define MUESTRAS_RMS         128

void tarea_sensor_rms(void *pvParameters) {
    float muestras[MUESTRAS_RMS];

    while (1) {
        float suma_cuadrados = 0.0f;

        for (int i = 0; i < MUESTRAS_RMS; i++) {
            // Simulación de lectura de sensor I2C en voltios
            float valor = leer_sensor_i2c();
            muestras[i] = valor;
            suma_cuadrados += valor * valor;

            // Ceder tiempo para no ahogar el procesador
            vTaskDelay(pdMS_TO_TICKS(1));
        }

        // Cálculo matemático del valor eficaz RMS
        float valor_rms = sqrtf(suma_cuadrados / MUESTRAS_RMS);
        printf("[TELEMETRÍA]: Valor RMS = %.3f V\n", valor_rms);

        // Alimentar Watchdog y ceder control al scheduler de FreeRTOS
        esp_task_wdt_reset();
        vTaskDelay(pdMS_TO_TICKS(50));
    }
}
